import android.app.UiAutomation;
import android.os.*;
import android.view.accessibility.AccessibilityNodeInfo;
public final class GpuRefreshLayoutProbe {
 public static void main(String[] args)throws Exception{
  String auto=GpuGridProbe.settings("get","system","accelerometer_rotation"),rotation=GpuGridProbe.settings("get","system","user_rotation");
  HandlerThread t=new HandlerThread("refresh-layout");t.start();Object c=Class.forName("android.app.UiAutomationConnection").getConstructor().newInstance();UiAutomation a=(UiAutomation)UiAutomation.class.getConstructor(Looper.class,Class.forName("android.app.IUiAutomationConnection")).newInstance(t.getLooper(),c);GpuRadioProbe.automation=a;GpuApiProbe.a=a;GpuRefreshProbe.automation=a;
  try{UiAutomation.class.getMethod("connect").invoke(a);android.accessibilityservice.AccessibilityServiceInfo i=a.getServiceInfo();i.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;a.setServiceInfo(i);Thread.sleep(900);
   for(boolean dark:new boolean[]{false,true}){
    GpuChromeProbe.tab("Home");GpuApiProbe.click(dark?"home-appearance-dark":"home-appearance-light");GpuUiProbe.waitText("home-appearance-resolved",dark?"Dark":"Light");GpuChromeProbe.tab("API");GpuApiProbe.click("api-refresh");GpuUiProbe.waitText("pull-refresh-count","0");GpuShareLayoutProbe.themePixel(dark);GpuRadioProbe.screenshot(dark?"gpu-refresh-layout-dark":"gpu-refresh-layout-light");
    GpuApiProbe.click("pull-refresh-start");GpuUiProbe.waitText("pull-refresh-status","Refreshing...");GpuUiProbe.waitText("pull-refresh-count","1");AccessibilityNodeInfo start=GpuApiProbe.node("pull-refresh-start");GpuUiProbe.check(!start.isEnabled(),"start disabled during refresh");start.recycle();GpuUiProbe.check(!GpuApiProbe.text("pull-refresh-time").equals("Never"),"refresh timestamp");GpuApiProbe.click("pull-refresh-stop");GpuUiProbe.waitText("pull-refresh-status","Idle");
    GpuRefreshProbe.top();GpuRefreshProbe.drag(0,30,false);GpuUiProbe.waitText("pull-refresh-count","1");GpuRefreshProbe.top();GpuRefreshProbe.drag(250,10,false);GpuUiProbe.waitText("pull-refresh-count","1");GpuRefreshProbe.top();GpuRefreshProbe.drag(0,650,true);GpuUiProbe.waitText("pull-refresh-count","1");GpuRefreshProbe.systemInterrupt();GpuRefreshProbe.top();GpuRefreshProbe.drag(0,650,false);GpuUiProbe.waitText("pull-refresh-count","2");GpuUiProbe.waitText("pull-refresh-status","Refreshing...");GpuRadioProbe.screenshot(dark?"gpu-refresh-gesture-dark":"gpu-refresh-gesture-light");
    if(!dark){GpuGridProbe.settings("put","system","accelerometer_rotation","0");GpuGridProbe.settings("put","system","user_rotation","1");Thread.sleep(1200);android.graphics.Bitmap shot=a.takeScreenshot();try{GpuUiProbe.check(shot.getWidth()>shot.getHeight(),"actual landscape");}finally{shot.recycle();}GpuUiProbe.waitText("pull-refresh-count","2");GpuUiProbe.waitText("pull-refresh-status","Refreshing...");GpuRadioProbe.screenshot("gpu-refresh-layout-landscape");GpuGridProbe.settings("put","system","user_rotation",rotation);GpuGridProbe.settings("put","system","accelerometer_rotation",auto);Thread.sleep(1000);}
    GpuChromeProbe.back();GpuApiProbe.click("api-refresh");GpuUiProbe.waitText("pull-refresh-count","0");GpuUiProbe.waitText("pull-refresh-status","Idle");GpuChromeProbe.back();
   }
   GpuChromeProbe.tab("Home");GpuApiProbe.click("home-appearance-light");GpuUiProbe.waitText("home-appearance-resolved","Light");System.out.println("PASS refresh light/dark cards, API start/stop, short/horizontal/canceled pulls, system shade interruption, physical pull, landscape state and reentry cleanup");
  }catch(Throwable error){error.printStackTrace();throw error;}finally{GpuGridProbe.settings("put","system","user_rotation",rotation);GpuGridProbe.settings("put","system","accelerometer_rotation",auto);UiAutomation.class.getMethod("disconnect").invoke(a);t.quitSafely();}
 }
}
